import { FREE_SUBSCRIPTION, PLANS } from '@proton/payments';
import { CYCLE } from '@proton/shared/lib/constants';
import { Renew } from '@proton/shared/lib/interfaces';
import { PLANS_MAP, subscriptionMock, upcomingSubscriptionMock } from '@proton/testing/data';

import {
    countriesWithStates,
    getBillingAddressStatus,
    notHigherThanAvailableOnBackend,
    subscriptionExpires,
} from './payment';

describe('subscriptionExpires()', () => {
    it('should handle the case when subscription is not loaded yet', () => {
        expect(subscriptionExpires()).toEqual({
            subscriptionExpiresSoon: false,
            renewDisabled: false,
            renewEnabled: true,
            expirationDate: null,
        });
    });

    it('should handle the case when subscription is free', () => {
        expect(subscriptionExpires(FREE_SUBSCRIPTION as any)).toEqual({
            subscriptionExpiresSoon: false,
            renewDisabled: false,
            renewEnabled: true,
            expirationDate: null,
        });
        expect(subscriptionExpires(FREE_SUBSCRIPTION, true)).toEqual(subscriptionExpires(FREE_SUBSCRIPTION));
    });

    it('should handle non-expiring subscription', () => {
        expect(subscriptionExpires(subscriptionMock)).toEqual({
            subscriptionExpiresSoon: false,
            planName: 'Proton Unlimited',
            renewDisabled: false,
            renewEnabled: true,
            expirationDate: null,
        });
    });

    it('should handle expiring subscription', () => {
        expect(
            subscriptionExpires({
                ...subscriptionMock,
                Renew: Renew.Disabled,
            })
        ).toEqual({
            subscriptionExpiresSoon: true,
            planName: 'Proton Unlimited',
            renewDisabled: true,
            renewEnabled: false,
            expirationDate: subscriptionMock.PeriodEnd,
        });
    });

    it('should handle the case when the upcoming subscription expires', () => {
        expect(
            subscriptionExpires({
                ...subscriptionMock,
                UpcomingSubscription: {
                    ...upcomingSubscriptionMock,
                    Renew: Renew.Disabled,
                },
            })
        ).toEqual({
            subscriptionExpiresSoon: true,
            planName: 'Proton Unlimited',
            renewDisabled: true,
            renewEnabled: false,
            expirationDate: upcomingSubscriptionMock.PeriodEnd,
        });
    });

    it('should handle the case when the upcoming subscription does not expire', () => {
        expect(
            subscriptionExpires({
                ...subscriptionMock,
                UpcomingSubscription: {
                    ...upcomingSubscriptionMock,
                    Renew: Renew.Enabled,
                },
            })
        ).toEqual({
            subscriptionExpiresSoon: false,
            planName: 'Proton Unlimited',
            renewDisabled: false,
            renewEnabled: true,
            expirationDate: null,
        });
    });

    it.each([
        { isCancellation: true, renew: Renew.Enabled },
        { isCancellation: false, renew: Renew.Disabled },
    ])(
        'uses the current term when cancellation is $isCancellation and renew is $renew',
        ({ isCancellation, renew }) => {
            const subscription = {
                ...subscriptionMock,
                Renew: renew,
                Plans: [{ ...subscriptionMock.Plans[0], Title: 'Current plan' }],
                UpcomingSubscription: {
                    ...upcomingSubscriptionMock,
                    Renew: Renew.Enabled,
                    Plans: [{ ...upcomingSubscriptionMock.Plans[0], Title: 'Future plan' }],
                },
            };

            expect(subscriptionExpires(subscription, isCancellation)).toEqual({
                subscriptionExpiresSoon: true,
                planName: 'Current plan',
                renewDisabled: true,
                renewEnabled: false,
                expirationDate: subscriptionMock.PeriodEnd,
            });
        }
    );
});

